<template>
  <div :class="cn('relative w-full')">
    <Input v-model="search" class="pl-10 shadow-sm" :placeholder="placeholder" />
    <span class="absolute start-0 inset-y-0 flex items-center justify-center px-4">
      <Search :class="cn('size-4', !search && 'text-muted-foreground')" />
    </span>
    <XIcon
      v-if="search && search.length > 0"
      class="h-4 w-4 ml-2 shrink-0 absolute right-4 top-[0.75rem] cursor-pointer"
      @click.stop.prevent="search = null"
    />
  </div>
</template>

<script setup lang="ts">
import { Search, XIcon } from 'lucide-vue-next';
import { cn } from '@/lib/utils';

const route = useRoute();
const props = withDefaults(
  defineProps<{
    query: string | null | undefined;
    propertyName: string;
    placeholder: string;
  }>(),
  {}
);
const search = ref<string | undefined | null>(props.query);

watchDebounced(
  search,
  async (newVal: string | undefined | null) => {
    await navigateTo({
      name: route.name,
      params: route.params,
      query: {
        ...route.query,
        page: 1,
        [props.propertyName]: newVal && newVal.length > 0 ? newVal : undefined,
      },
    });
  },
  { debounce: 300 }
);
watch(
  () => props.query,
  (newVal) => {
    if (newVal !== search.value) search.value = newVal;
  }
);
</script>
